CREATE OR REPLACE PROCEDURE dswtdir1_dbo.sp_memo_preload_scenario_transform_rules_scn20_finalize()
 LANGUAGE plpgsql
AS $procedure$
BEGIN
    /* 79 EXEC [dbo].[srMEMOAPP_Scenario_TDIR1_MemoApp_MemoApp_Source_AllProponents_zScenario_ScnInitialUpd] --Autogenerated for R2. */
    UPDATE dswtdir1_dbo.stmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_ssis
    SET zscenario_scninitial =
    CASE
        WHEN zscenario1 = 1 THEN 'Scenario1'
        WHEN zscenario2 = 1 THEN 'Scenario2'
        WHEN zscenario3 = 1 THEN 'Scenario3'
        WHEN zscenario4 = 1 THEN 'Scenario4'
        WHEN zscenario5 = 1 THEN 'Scenario5'
        WHEN zscenario2_inscn6 = 1 THEN 'Scenario2_inScn6'
        WHEN zscenario3_inscn6 = 1 THEN 'Scenario3_inScn6'
        WHEN zscenario4_inscn6 = 1 THEN 'Scenario4_inScn6'
        WHEN zscenario5_inscn6 = 1 THEN 'Scenario5_inScn6'
        WHEN zscenario8r = 1 THEN 'Scenario8R'
        WHEN zscenario8m = 1 THEN 'Scenario8M'
        WHEN zscenario9 = 1 THEN 'Scenario9'
        WHEN zscenario10 = 1 THEN 'Scenario10'
    END
        WHERE zscenario_scninitial IS NULL;
    /* 80 EXEC [dbo].[srMEMOAPP_Scenario_TDIR1_MemoApp_MemoApp_Source_AllProponents_zScenario_Counter_OrderBy_ScnInitialUpd] --Autogenerated for R2. */
    UPDATE dswtdir1_dbo.stmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_ssis
    SET zscenario_counter_orderby_scninitial =
    CASE
        WHEN zscenario1 = 1 THEN zscenario1_counter_orderby
        WHEN zscenario2 = 1 THEN zscenario2_counter_orderby
        WHEN zscenario3 = 1 THEN zscenario3_counter_orderby
        WHEN zscenario4 = 1 THEN zscenario4_counter_orderby
        WHEN zscenario5 = 1 THEN zscenario5_counter_orderby
        WHEN zscenario2_inscn6 = 1 THEN zscenario2_inscn6_counter_orderby
        WHEN zscenario3_inscn6 = 1 THEN zscenario3_inscn6_counter_orderby
        WHEN zscenario4_inscn6 = 1 THEN zscenario4_inscn6_counter_orderby
        WHEN zscenario5_inscn6 = 1 THEN zscenario5_inscn6_counter_orderby
        WHEN zscenario8r = 1 THEN zscenario8r_counter_orderby
        WHEN zscenario8m = 1 THEN zscenario8m_counter_orderby
        WHEN zscenario9 = 1 THEN zscenario9_counter_orderby
        WHEN zscenario10 = 1 THEN zscenario10_counter_orderby
    END
        WHERE zscenario_counter_orderby_scninitial IS NULL;
    /* 81 EXEC [dbo].[srMEMOAPP_Scenario_TDIR1_MemoApp_MemoApp_Source_AllProponents_zScenario_zRowNumber_Min_ScnInitialUpd] --Autogenerated for R2. */
    UPDATE dswtdir1_dbo.stmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_ssis
    SET zscenario_zrownumber_min_scninitial =
    CASE
        WHEN zscenario1 = 1 THEN zscenario1_zrownumber_min
        WHEN zscenario2 = 1 THEN zscenario2_zrownumber_min
        WHEN zscenario3 = 1 THEN zscenario3_zrownumber_min
        WHEN zscenario4 = 1 THEN zscenario4_zrownumber_min
        WHEN zscenario5 = 1 THEN zscenario5_zrownumber_min
        WHEN zscenario2_inscn6 = 1 THEN zscenario2_inscn6_zrownumber_min
        WHEN zscenario3_inscn6 = 1 THEN zscenario3_inscn6_zrownumber_min
        WHEN zscenario4_inscn6 = 1 THEN zscenario4_inscn6_zrownumber_min
        WHEN zscenario5_inscn6 = 1 THEN zscenario5_inscn6_zrownumber_min
        WHEN zscenario8r = 1 THEN zscenario8r_zrownumber_min
        WHEN zscenario8m = 1 THEN zscenario8m_zrownumber_min
        WHEN zscenario9 = 1 THEN zscenario9_zrownumber_min
        WHEN zscenario10 = 1 THEN zscenario10_zrownumber_min
    END
        WHERE zscenario_zrownumber_min_scninitial IS NULL;
    /* 82 EXEC [dbo].[srMEMOAPP_Scenario_TDIR1_MemoApp_MemoApp_Source_AllProponents_zScenario_zRowNumber_Max_ScnInitialUpd] --Autogenerated for R2. */
    UPDATE dswtdir1_dbo.stmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_ssis
    SET zscenario_zrownumber_max_scninitial =
    CASE
        WHEN zscenario1 = 1 THEN zscenario1_zrownumber_max
        WHEN zscenario2 = 1 THEN zscenario2_zrownumber_max
        WHEN zscenario3 = 1 THEN zscenario3_zrownumber_max
        WHEN zscenario4 = 1 THEN zscenario4_zrownumber_max
        WHEN zscenario5 = 1 THEN zscenario5_zrownumber_max
        WHEN zscenario2_inscn6 = 1 THEN zscenario2_inscn6_zrownumber_max
        WHEN zscenario3_inscn6 = 1 THEN zscenario3_inscn6_zrownumber_max
        WHEN zscenario4_inscn6 = 1 THEN zscenario4_inscn6_zrownumber_max
        WHEN zscenario5_inscn6 = 1 THEN zscenario5_inscn6_zrownumber_max
        WHEN zscenario8r = 1 THEN zscenario8r_zrownumber_max
        WHEN zscenario8m = 1 THEN zscenario8m_zrownumber_max
        WHEN zscenario9 = 1 THEN zscenario9_zrownumber_max
        WHEN zscenario10 = 1 THEN zscenario10_zrownumber_max
    END
        WHERE zscenario_zrownumber_max_scninitial IS NULL;
    /* 83 EXEC [dbo].[srMEMOAPP_Scenario_TDIR1_MemoApp_MemoApp_Source_AllProponents_zScenario_Counts_ScnInitialUpd] --Autogenerated for R2. */
    UPDATE dswtdir1_dbo.stmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_ssis
    SET zscenario_counts_scninitial =
    CASE
        WHEN zscenario1 = 1 THEN zscenario1_counts
        WHEN zscenario2 = 1 THEN zscenario2_counts
        WHEN zscenario3 = 1 THEN zscenario3_counts
        WHEN zscenario4 = 1 THEN zscenario4_counts
        WHEN zscenario5 = 1 THEN zscenario5_counts
        WHEN zscenario2_inscn6 = 1 THEN zscenario2_inscn6_counts
        WHEN zscenario3_inscn6 = 1 THEN zscenario3_inscn6_counts
        WHEN zscenario4_inscn6 = 1 THEN zscenario4_inscn6_counts
        WHEN zscenario5_inscn6 = 1 THEN zscenario5_inscn6_counts
        WHEN zscenario8r = 1 THEN zscenario8r_counts
        WHEN zscenario8m = 1 THEN zscenario8m_counts
        WHEN zscenario9 = 1 THEN zscenario9_counts
        WHEN zscenario10 = 1 THEN zscenario10_counts
    END
        WHERE zscenario_counts_scninitial IS NULL;
    /* 84 EXEC [dbo].[srMEMOAPP_Scenario_TDIR1_MemoApp_MemoApp_Source_AllProponents_zCounter_ScnInitialUpd] --For for Scenarios 1 to 5, update zCounter_ScnInitial with (dense_Rank() over(order by zScenario_ScnInitial, zScenario_Counter_OrderBy_ScnInitial, zInputFileName)) */
    WITH cte_srmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_zcounter_scninitialupdsel_ssis
    AS (SELECT
        zcounter_scninitial, etl_db_dbo.fn_padstringwithcharacter((DENSE_RANK() OVER (ORDER BY zscenario_scninitial, zscenario_counter_orderby_scninitial, zinputfilename)), 0, 10) AS zcounter_scninitialnew
        FROM dswtdir1_dbo.stmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_ssis
        WHERE zcounter_scninitial IS NULL AND LOWER(zscenario_scninitial) NOT LIKE LOWER('%Scn6%'))
    UPDATE cte_srmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_zcounter_scninitialupdsel_ssis
    SET zcounter_scninitial = zcounter_scninitialnew;
    /* 85 EXEC [dbo].[srMEMOAPP_Scenario_TDIR1_MemoApp_MemoApp_Source_AllProponents_zCounter_ScnInitial_Custom_Upd] --For for Scenarios 1 to 5, Overwrite zCounter_ScnInitial to use YDDD with last 6 digits of counter to handle 999999 counters per processing whil e maintaining uniqueness on DCS. Inactivate trMEMOAPP_Preload_zCounter_CustomUpdSel. */
    UPDATE dswtdir1_dbo.stmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_ssis
    SET zcounter_scninitial = CONCAT(RIGHT(date_part('year', clock_timestamp()), 1), etl_db_dbo.fn_padstringwithcharacter(CAST (to_char(clock_timestamp()::TIMESTAMP, 'DDD') AS INT), 0, 3), RIGHT(zcounter_scninitial, 6))
        WHERE LOWER(zscenario_scninitial) NOT LIKE LOWER('%Scn6%');
    /* 86 EXEC [dbo].[srMEMOAPP_Scenario_TDIR1_MemoApp_MemoApp_Source_AllProponents_zCounter_ScnInitial_Scn6_Upd] --For Scenario6, Update zCounter_ScnInitial explicitly to handle different counters New Accrual Doc lines. */
    WITH cte_srmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_zcounter_scninitial_scn6_updsel_ssis
    AS (SELECT
        zscenario_scninitial, zinputfilename, zrownumber, zcounter_scninitial, etl_db_dbo.fn_padstringwithcharacter((CAST ((SELECT
            MAX(zcounter_scninitial)
            FROM dswtdir1_dbo.stmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_ssis
            WHERE LOWER(zscenario_scninitial) NOT LIKE LOWER('%Scn6%')) AS INTEGER) + (((DENSE_RANK() OVER (ORDER BY zscenario_scninitial, zscenario_counter_orderby_scninitial, zinputfilename)) * 2) - 1)), 0, 10) AS zcounter_scninitialnew
        FROM dswtdir1_dbo.stmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_ssis
        WHERE LOWER(zscenario_scninitial) LIKE LOWER('%Scn6%'))
    UPDATE cte_srmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_zcounter_scninitial_scn6_updsel_ssis
    SET zcounter_scninitial = zcounter_scninitialnew;
    /* 87 EXEC [dbo].[srMEMOAPP_Scenario_TDIR1_MemoApp_MemoApp_Source_AllProponents_zCounterLineItem_ScnInitialUpd] --Update Target from Source */
    WITH cte_srmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_zcounterlineitem_scninitialupdsel_ssis
    AS (SELECT
        x.zcounterlineitem_scninitial, (ROW_NUMBER() OVER (PARTITION BY zcounter_scninitial ORDER BY zcounter_scninitial, invoice_number, vendor_code, accrual_doc_number, vat_code, gl_natural_code, company_code, cost_center_code, description, assignment, gross_invoice_amount)) AS zcounterlineitem_scninitialnew
        FROM dswtdir1_dbo.stmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_ssis AS x
        WHERE (x.zcounterlineitem_scninitial IS NULL))
    UPDATE cte_srmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_zcounterlineitem_scninitialupdsel_ssis
    SET zcounterlineitem_scninitial = zcounterlineitem_scninitialnew;
    /* 88 EXEC [dbo].[srMEMOAPP_Scenario_TDIR1_MemoApp_MemoApp_Source_AllProponents_Invoice_DateUpd] --Update Invoice Date to Trim Timestamp */
    UPDATE dswtdir1_dbo.stmemoapp_scenario_tdir1_memoapp_memoapp_source_allproponents_ssis AS x
    SET invoice_date = (CASE
        WHEN LOWER(invoice_date) SIMILAR TO LOWER('% %') THEN SUBSTR(invoice_date, 0, (STRPOS(invoice_date, ' ')))
        ELSE invoice_date
    END);
END;
$procedure$
